"""Run shared semantic cases against a fresh, isolated native arcade session."""
from pathlib import Path
import sys
PROJECT=Path(__file__).resolve().parents[3]
game,rep,run_dir=sys.argv[1],int(sys.argv[2]),Path(sys.argv[3])
source=(PROJECT/'engenharia-reversa/ferramentas/capturar_animacoes.py').read_text(encoding='utf-8')
prefix=source[:source.index("if game=='ssf2tu':\n for frame")]
prefix=prefix.replace("SAVE=Path(r'D:/projetos/Mortal Kombat vs Street Fighter/engenharia-reversa/execucao-animacoes')/sys.argv[1]", "SAVE=Path("+repr(str(run_dir/'execution'/game/f'rep-{rep}'))+")")
prefix=prefix.replace("OUT=Path(r'D:/projetos/Mortal Kombat vs Street Fighter/engenharia-reversa/animacoes')/('ryu' if game=='ssf2tu' else 'scorpion')", "OUT=Path("+repr(str(run_dir/'original'/game/f'rep-{rep}'))+")")
setup=source[source.index("if game=='ssf2tu':\n for frame"):source.index('def sfdata(b):')]
# P2's default is Ken; move one row up to choose Ryu for an exact mirror fixture.
setup=setup.replace('ticks([0],6,second=[0]);ticks([],850)', 'ticks([],3,second=[4]);ticks([],5);ticks([0],6,second=[0]);ticks([],850)')
data=source[source.index('def sfdata(b):'):source.index("print('BASELINE'")]
body='\nDATA=(PROJECT/\'engenharia-reversa/entradas/ssf2tu-68k-data-be.bin\').read_bytes() if game==\'ssf2tu\' else b\'\'\nsuite=json.loads(Path(sys.argv[4]).read_text(encoding=\'utf-8\'))\ndef observe(b):\n if game==\'umk3\':\n  off=lambda a:0x2c19+(a-0x1000000)//8\n  objects=[struct.unpack_from(\'<I\',b,off(a))[0] for a in [0x10609d0,0x1061580]];players=[]\n  for o,hp in zip(objects,[0x1060a60,0x1061610]):\n   a=off(o);players.append({\'x\':struct.unpack_from(\'<i\',b,a+16)[0]/65536,\'y\':struct.unpack_from(\'<i\',b,a+20)[0]/65536,\'pose\':hex(struct.unpack_from(\'<I\',b,a+58)[0]),\'facing\':-1 if struct.unpack_from(\'<H\',b,a+30)[0]&16 else 1,\'health\':struct.unpack_from(\'<H\',b,off(hp))[0],\'state\':None,\'boxes\':[]})\n  return {\'players\':players,\'camera\':struct.unpack_from(\'<h\',b,off(0x105dae0))[0]}\n read=lambda a,n:bytes(b[0x3d346+(((a+i)&65535)^1)] for i in range(n));num=lambda a,n:int.from_bytes(read(a,n),\'big\');players=[]\n for base in [0xff844e,0xff884e]:\n  ptr=num(base+0x1a,4);table=num(base+0x34,4);boxes=[]\n  if 0<ptr<len(DATA)-32 and 0<table<len(DATA)-16:\n   for offset,ident,stride,kind in [(0,8,4,\'hurt\'),(2,9,4,\'hurt\'),(4,10,4,\'hurt\'),(6,12,16,\'attack\'),(8,13,4,\'push\')]:\n    index=DATA[ptr+ident]\n    if not index:continue\n    address=table+int.from_bytes(DATA[table+offset:table+offset+2],\'big\',signed=True)+index*stride\n    if not 0<=address<len(DATA)-16:continue\n    x,y,rx,ry=struct.unpack_from(\'>bbBB\',DATA,address)\n    if kind==\'attack\' and DATA[address+5]>=128:x=-DATA[address+5]\n    boxes.append({\'kind\':kind,\'id\':index,\'address\':hex(address),\'x\':x-rx,\'y\':y-ry,\'w\':rx*2,\'h\':ry*2})\n  players.append({\'x\':int.from_bytes(read(base+6,2),\'big\',signed=True),\'y\':int.from_bytes(read(base+10,2),\'big\',signed=True),\'pose\':hex(ptr),\'health\':num(base+0x2c,2),\'facing\':1 if num(base+0x12,1) else -1,\'state\':list(read(base+2,4)),\'boxes\':boxes,\'table\':hex(table)})\n return {\'players\':players,\'camera\':num(0xff8ed4,2)}\ndef visual(b,obs,port):\n if game==\'umk3\':return None\n records=[];alt=[]\n for dest,start in [(records,0x9346),(alt,0xb346)]:\n  for offset in range(start,start+0x2000,8):\n   x,y,code,attr=struct.unpack_from(\'<4H\',b,offset)\n   if attr&31==(1 if port==0 else 16):dest.append([x,y,code,attr])\n return {\'p1_objects\':records,\'p1_objects_alt\':alt,\'palette_words\':list(struct.unpack_from(\'<16H\',b,0xd346+(1 if port==0 else 16)*32)),\'object_palette_words\':list(struct.unpack_from(\'<512H\',b,0xd346)),\'frame\':obs[\'players\'][port][\'pose\'],\'x\':obs[\'players\'][port][\'x\'],\'y\':obs[\'players\'][port][\'y\']}\ndef keys(v):\n out=list(v.get(\'raw\',[]))\n for field,button in [(\'down\',5),(\'up\',4)]:\n  if v.get(field):out.append(button)\n if v.get(\'x\'):out.append(7 if v[\'x\']>0 else 6)\n return out\ninitial=getdata(baseline);assert initial[\'char_p1\']==initial[\'char_p2\']==(18 if game==\'umk3\' else 0)\nresults=[]\nfor c in suite[\'cases\']:\n restore(baseline);ticks([],3)\n for seg in c.get(\'setup\',[]):ticks(keys(seg.get(\'p1\',{})),seg[\'frames\'],keys(seg.get(\'p2\',{})))\n start=observe(state());folder=OUT/c[\'id\'];folder.mkdir(exist_ok=True);samples=[]\n script=[seg for seg in c[\'segments\'] for _ in range(seg[\'frames\'])]\n for i,seg in enumerate(script):\n  before=observe(state());ticks(keys(seg.get(\'p1\',{})),1,keys(seg.get(\'p2\',{})));b=state();after=observe(b)\n  shot=None\n  if i in suite[\'checkpoints\'] or c.get(\'all_video\'):shot=f"{i:03}.png";latest.save(folder/shot)\n  render=[visual(b,after,p) for p in [0,1]] if c.get(\'visual\',True) else None\n  samples.append({\'sample\':i,\'before\':before,\'after\':after,\'input\':[seg.get(\'p1\',{}),seg.get(\'p2\',{})],\'render\':render,\'screenshot\':shot})\n result={\'id\':c[\'id\'],\'meta\':c.get(\'meta\',{}),\'initial\':start,\'samples\':samples}\n (folder/\'trace.json\').write_text(json.dumps(result),encoding=\'utf-8\');results.append({\'id\':c[\'id\'],\'file\':c[\'id\']+\'/trace.json\',\'initial\':start})\n print(\'CASE\',game,rep,c[\'id\'],start[\'players\'][1][\'x\']-start[\'players\'][0][\'x\'],\'life\',samples[-1][\'after\'][\'players\'][1][\'health\'],flush=True)\n(OUT/\'index.json\').write_text(json.dumps({\'game\':game,\'rep\':rep,\'fps\':av.timing.fps,\'char_ids\':[initial[\'char_p1\'],initial[\'char_p2\']],\'baseline\':observe(baseline),\'cases\':results,\'options\':{k:v.decode() for k,v in variables.items()}},indent=2),encoding=\'utf-8\')\nlib.retro_unload_game();lib.retro_deinit();print(\'DONE\',game,rep,flush=True)\n'
exec(compile(prefix+setup+data+body,str(__file__),'exec'))
